calcBase:
function calcBase(bks,apt,stayOverride,months){
  const _nMo = Math.max(1, parseInt(months)||1);
  // Exclude maintenance/owner blocks from financial calculations
  bks = bks.filter(isRevenueBooking);
  const gross    =bks.reduce((s,b)=>s+(b.gross||0),0);
  const ct       =bks.reduce((s,b)=>s+(b.ct||0),0);
  const vat      =bks.reduce((s,b)=>s+(b.vat||0),0);
  const at       =bks.reduce((s,b)=>s+(b.at||0),0);
  const totTax   =ct+vat+at;
  const cleanH   =bks.reduce((s,b)=>s+(b.cleanH||0),0); // Hosthub cleaning (for reference)
  const svc      =bks.reduce((s,b)=>s+(b.svc||0),0);
  const pchg     =bks.reduce((s,b)=>s+(b.pchg||0),0);
  const totPay   =bks.reduce((s,b)=>s+(b.payout||0),0);
  const netBkVal =bks.reduce((s,b)=>s+(b.nbv||0),0);
  const trHost   =bks.reduce((s,b)=>s+(b.trHost||0),0);
  const trChan   =bks.reduce((s,b)=>s+(b.trChan||0),0);
  const thHost   =bks.reduce((s,b)=>s+(b.thHost||0),0);
  const bvPreVat =bks.reduce((s,b)=>s+(b.bvPrevat||0),0);
  // Configured cleaning fee (ex-VAT)
  // Cancelled bookings don't incur a cleaning fee (no stay happened)
  const activeBks = bks.filter(b => !b.cancelled);
  const cleanStays = (stayOverride !== undefined && stayOverride !== null) ? stayOverride : activeBks.length;
  const configCl = parseFloat(apt?.cleaningFee||0)*cleanStays;
  // When vatOnFees is ON, cleaning cost to owner = configCl × 1.24 (fee + 24% VAT)
  // The full VAT-inclusive cleaning amount must be deducted before applying management %
  const cleanVat   = apt?.vatOnFees ? configCl * 0.24 : 0;
  const cleanTotal = configCl + cleanVat;
  // Management base = Gross - Greek taxes - Cleaning (incl. VAT if applicable) - Platform fees
  // Management base on pre-VAT values (booking_value_pre_vat from GR taxes API)
  // Falls back to gross-ct-vat if API data not yet fetched
  // Management base: pre-VAT booking value minus accommodation tax, cleaning (ex-VAT only), platform fees
  // Cleaning VAT is NOT deducted from base — it is an Elysian service charge, not a base deduction
  // Business tax (Επιτηδεύματος): fixed monthly amount — computed first as it reduces the mgmt fee base
  // Charged once per calendar month the report period covers (×_nMo)
  const bt = apt?.businessTax ? (parseFloat(apt?.businessTaxAmt)||50) * _nMo : 0;
  // Management fee base = Revenue - Taxes (per profile flags) - Platform Fees - Business Tax - Cleaning
  const vatForBase = (apt?.deductVAT !== false) ? vat : 0;
  const atForBase  = apt?.municipalityTax ? at : 0;
  const base = gross - ct - vatForBase - atForBase - svc - pchg - bt - configCl;
  return{base,gross,ct,vat,at,totTax,cleanH,configCl,cleanVat,cleanTotal,svc,pchg,totPay,netBkVal,trHost,trChan,thHost,bvPreVat,bt,cleanStays,cleanStaysAuto:activeBks.length};
}

calcAptPacket:
function calcAptPacket(a, aBks, aExps, getEA, getEAVat, cleanOv, months) {
  const _nMo = Math.max(1, parseInt(months)||1);
  const m    = calcBase(aBks, a, cleanOv, _nMo);
  const rate = parseFloat(a.mgmtFee||0)/100;
  const mf   = Math.max(0, m.base) * rate;             // clamp per apartment
  const hasVat = !!a.vatOnFees;
  // Fixed charges are monthly amounts — charged once per month the period covers
  const fixedCh = (a.fixedCharges||[]).reduce((s,f)=>s+(parseFloat(f.amount)||0),0) * _nMo;
  const cleanDeduct = (a.deductCleaning !== false) ? m.configCl : 0;
  const elysianVat  = hasVat ? (mf + cleanDeduct + fixedCh) * 0.24 : 0;
  const totExp = aExps.reduce((s,e)=>s+getEA(e, a.id),0);
  const expVat = hasVat ? aExps.reduce((s,e)=>s+getEAVat(e, a.id),0) : 0;
  const totExpIncl = totExp + expVat;
  const ctDeduct  = (a.deductCT  !== false) ? m.ct  : 0;
  const vatDeduct = (a.deductVAT !== false) ? m.vat : 0;
  const atDeduct  = a.municipalityTax ? m.at : 0;
  const payout = m.gross - m.svc - m.pchg - ctDeduct - vatDeduct - atDeduct
    - mf - (m.bt||0) - cleanDeduct - elysianVat - fixedCh - totExpIncl;
  const b2bRem = a.b2b ? payout + ctDeduct + vatDeduct + atDeduct : 0;
  const netEarnings = m.gross - m.ct - vatDeduct - atDeduct - m.svc - m.pchg - m.bt
    - cleanDeduct * (hasVat ? 1.24 : 1)
    - fixedCh    * (hasVat ? 1.24 : 1)
    - totExpIncl;
  return { a, m, rate, mf, hasVat, fixedCh, cleanDeduct, elysianVat,
           totExp, expVat, totExpIncl, ctDeduct, vatDeduct, atDeduct,
           payout, b2bRem, netEarnings, exps: aExps, months: _nMo };
}

